<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigSenderNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigSenderNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withSenderName,
 * getSenderName/senderName accessors, and isSenderNameChanged with/without original.
 */
class SmtpOutboundConfigSenderNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSenderName creates a new instance with the SenderName set
     * from a string value, and getSenderName returns the primitive string.
     */
    public function testWithSenderNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderNameAccessorUnitTest();

        // Act
        $result = $holder->withSenderName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSenderName());
    }
    /**
     * Asserts that withsenderName has access to the value object
     * from a string value, and getSenderName returns the primitive string.
     */
    public function testWithSenderNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderNameAccessorUnitTest();

        // Act
        $result = $holder->withSenderName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->senderName()->value());
    }
    public function testChangedSenderName(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderNameAccessorUnitTest();
        $original = $holder->withSenderName( 'one');
        $same = $holder->withSenderName( 'one');
        $modified = $holder->withSenderName('other');

        // Act
        $unchanged = $holder->isSenderNameChanged();
        $withSame = $original->isSenderNameChanged( $same );
        $withDiferent = $original->isSenderNameChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigSenderNameAccessorUnitTest
{
  use SmtpOutboundConfigSenderNameAccessor;
}
